#[no_mangle]
pub unsafe extern "C" fn construct_response(
    mut buf: *mut UNICODE,
    mut R: ::core::ffi::c_int,
    mut c2rust_args: ...
) {
    let mut buf_start: *mut UNICODE = buf;
    let mut name: *mut UNICODE = ::core::ptr::null_mut::<UNICODE>();
    let mut vlist: ::core::ffi::VaListImpl;
    vlist = c2rust_args.clone();
    loop {
        let mut len: COUNT = 0;
        let mut S: STRING = ::core::ptr::null_mut::<STRING_TABLE_ENTRY_DESC>();
        S = SetAbsStringTableIndex(
            CommData.ConversationPhrases,
            (R - 1 as ::core::ffi::c_int) as COUNT,
        );
        strcpy(buf, GetStringAddress(S));
        len = strlen(buf) as COUNT;
        buf = buf.offset(len as ::core::ffi::c_int as isize);
        name = vlist.arg::<*mut UNICODE>();
        if !name.is_null() {
            len = strlen(name) as COUNT;
            strcpy(buf, name);
            buf = buf.offset(len as ::core::ffi::c_int as isize);
            R = vlist.arg::<::core::ffi::c_int>();
            if R == -1 as ::core::ffi::c_int as RESPONSE_REF as ::core::ffi::c_int {
                name = ::core::ptr::null_mut::<UNICODE>();
            }
        }
        if name.is_null() {
            break;
        }
    }
    *buf = '\0' as UNICODE;
    if buf_start == &raw mut shared_phrase_buf as *mut UNICODE
        && buf
            > (&raw mut shared_phrase_buf as *mut UNICODE)
                .offset(::core::mem::size_of::<[UNICODE; 2048]>() as isize)
    {
        log_add(
            log_Level::log_Fatal,
            b"Error: shared_phrase_buf size exceeded, please increase!\n\0".as_ptr()
                as *const ::core::ffi::c_char,
        );
        exit(1 as ::core::ffi::c_int);
    }
}
#[no_mangle]
pub unsafe extern "C" fn setSegue(mut segue: Segue) {
    match segue {
        Segue::Segue_peace => {
            uqm_lua_checked!(setGameStateUint(
                b"BATTLE_SEGUE\0".as_ptr() as *const ::core::ffi::c_char,
                0 as DWORD,
            ), ());
        }
        Segue::Segue_hostile => {
            uqm_lua_checked!(setGameStateUint(
                b"BATTLE_SEGUE\0".as_ptr() as *const ::core::ffi::c_char,
                1 as DWORD,
            ), ());
        }
        Segue::Segue_victory => {
            instantVictory = BOOLEAN::TRUE;
            uqm_lua_checked!(setGameStateUint(
                b"BATTLE_SEGUE\0".as_ptr() as *const ::core::ffi::c_char,
                1 as DWORD,
            ), ());
        }
        Segue::Segue_defeat => {
            uqm_lua_checked!(setGameStateUint(
                b"BATTLE_SEGUE\0".as_ptr() as *const ::core::ffi::c_char,
                0 as DWORD,
            ), ());
            GlobData.SIS_state.CrewEnlisted = !(0 as ::core::ffi::c_int) as COUNT;
            GlobData.Game_state.CurrentActivity = (GlobData.Game_state.CurrentActivity
                as ::core::ffi::c_int
                | C2Rust_Unnamed_0::CHECK_RESTART.0 as ::core::ffi::c_int) as ACTIVITY;
        }
        _ => {}
    };
}
#[no_mangle]
pub unsafe extern "C" fn getSegue() -> Segue {
    if uqm_lua_checked!(getGameStateUint(b"BATTLE_SEGUE\0".as_ptr() as *const ::core::ffi::c_char), Segue(0))
        == 0 as DWORD
    {
        if GlobData.SIS_state.CrewEnlisted as ::core::ffi::c_int
            == !(0 as ::core::ffi::c_int) as COUNT as ::core::ffi::c_int
            && GlobData.Game_state.CurrentActivity as ::core::ffi::c_int
                & C2Rust_Unnamed_0::CHECK_RESTART.0 as ::core::ffi::c_int != 0
        {
            return Segue::Segue_defeat
        } else {
            return Segue::Segue_peace
        }
    } else if instantVictory.0 != 0 {
        return Segue::Segue_victory
    } else {
        return Segue::Segue_hostile
    };
}
